import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import api from '../utils/api';

const Events = () => {
  const [events, setEvents] = useState([]);

  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const { data } = await api.get('/events');
        setEvents(data);
      } catch (error) {
        console.error('Failed to fetch events');
      }
    };
    fetchEvents();
  }, []);

  return (
    <div className="container mx-auto py-8">
      <h1 className="text-3xl font-bold mb-8">Events</h1>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {events.map((event) => (
          <div key={event._id} className="bg-white p-6 rounded-lg shadow-md">
            {event.image && <img src={`http://localhost:5000/${event.image}`} alt={event.title} className="w-full h-48 object-cover mb-4" />}
            <h2 className="text-xl font-bold mb-2">{event.title}</h2>
            <p className="text-gray-600 mb-2">{event.description}</p>
            <p className="text-sm">Date: {new Date(event.date).toDateString()}</p>
            <p className="text-sm">Venue: {event.venue}</p>
            <p className="text-sm">Category: {event.category}</p>
            <Link to={`/events/${event._id}`} className="mt-4 inline-block bg-blue-600 text-white px-4 py-2 rounded">View Details</Link>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Events;
